const archive='https://nilesnorthbusiness.weebly.com/uploads/3/7/2/1/37215033/2018_tdm_set.pdf';
const CASE_LIBRARY=[
 {id:'family',title:'A young family’s financial future',tag:'Official 2026 sample',source:SAMPLE,note:'Current official sample. Scenario summarized; original five indicators and judge questions.',scenario,indicators:[...indicators],questions:[...questions]},
 {id:'customer',title:'Customer before the coin',tag:'DECA source · practice adaptation',source:'https://www.decadirect.org/articles/case-study-of-the-week-the-customer-before-the-coin',note:'Based on DECA’s customer-relations case. Four published indicators plus confidentiality as a practice indicator. Two original practice questions.',scenario:'You are two district managers of Jefferson Bank. Customer surveys expose poor service across tellers, lending staff and other employees. Present a staff-training plan to the bank president that addresses customer expectations, understandable communication, the brand promise, community relationships, confidentiality and employee behavior. Include a rollout and measures of improvement.',indicators:['Explain finance professionals’ client-service responsibilities.','Explain positive customer relations.','Reinforce service orientation through communication.','Identify the company’s brand promise.','Protect client confidentiality (added practice indicator).'],questions:['How would you test whether employees communicate clearly?','How would you measure success after ninety days?']},
 {id:'cards',title:'Credit-card data and growth',tag:'2018 FTDM · practice adaptation',source:archive+'#page=73',note:'Archived FTDM case, pages 72–81. Five condensed learning targets; two paraphrased judge questions. Practice adaptation, not a new official case.',scenario:'As bank analysts, propose responsible credit-card growth using customer data, including revolving and full-payment accounts.',indicators:['Financial-information management','Data ethics','Financial technology','Customer-data analysis','Actionable recommendations'],questions:['How can revenue growth preserve member interests?','Could these analytical methods support other financial services?']},
 {id:'digital',title:'Digital banking for small businesses',tag:'2018 FTDM · practice adaptation',source:archive+'#page=82',note:'Archived FTDM case, pages 82–87. Five condensed learning targets; paraphrased questions. Read the source for the full brief.',scenario:'As business-banking specialists, explain technology, banking trends and customized services to small-business clients for a bank executive.',indicators:['Financial institutions','Banking trends','Technology impacts','Customer records','Financial-information management'],questions:['Which services still require a branch visit?','How would you address account closures and attract clients?']},
 {id:'lending',title:'Commercial property lending',tag:'2018 FTDM · practice adaptation',source:archive+'#page=88',note:'Archived FTDM case, pages 88 onward. Five practice learning targets; paraphrased questions. Research current requirements rather than relying on 2018 legal details.',scenario:'As senior bankers, explain commercial-property lending, collateral, limits, regulation and loan structures to an executive.',indicators:['Commercial lending','Business financing','Lending regulation','Collateral','Credit-risk evaluation'],questions:['Would you offer unsecured business loans? Why?','Should a recent loss automatically disqualify a borrower?']},
 {id:'fraud',title:'A credit union under phishing attack',tag:'Original FTDM-style practice',source:'https://www.deca.org/compete/financial-services-team-decision-making',note:'Original practice scenario, indicators and questions. Not an official DECA case.',scenario:'You are operations and member-services managers at Harbor Credit Union. In the last month, 18 members reported phishing texts impersonating the credit union; four members lost a combined $12,000. The CEO needs a 90-day response plan with a $15,000 budget. Recommend member communication, incident escalation, account safeguards, staff training and success measures. Avoid blaming victims, promising reimbursement before investigation, or exposing member details.',indicators:['Explain information privacy, security and confidentiality.','Identify risks affecting financial institutions.','Explain responsible client communication.','Evaluate costs and benefits of operational decisions.','Translate findings into actionable recommendations.'],questions:['How would you support a member who has already lost money?','How will you know the prevention program works?']},
 {id:'retirement',title:'Retirement benefits for a growing employer',tag:'Original FTDM-style practice',source:'https://www.deca.org/compete/financial-services-team-decision-making',note:'Original practice scenario, indicators and questions. All numbers are fictional.',scenario:'You are financial-services consultants advising a 25-person employer. The owner wants to introduce retirement benefits with an annual employer budget of $40,000. Employees have widely different ages, savings and financial knowledge. Compare plan options at a conceptual level, explain diversified investment choices and financial-market risks, recommend an employee-education program, and describe implementation costs. Identify missing facts and compliance checks rather than inventing legal requirements or guaranteed returns.',indicators:['Explain the need to save and invest.','Explain investment types.','Explain risk and diversification.','Analyze client needs and financial constraints.','Explain finance professionals’ client-service responsibilities.'],questions:['What would you say to an employee afraid of market losses?','How would you keep the program within the employer’s budget?']},
 {id:'cashflow',title:'A bakery’s working-capital squeeze',tag:'Original FTDM-style practice',source:'https://www.deca.org/compete/financial-services-team-decision-making',note:'Original practice scenario, indicators and questions. All financial data are fictional.',scenario:'You are business-banking advisors for a bakery with average monthly revenue of $40,000 and cash operating costs of $34,000. A wholesale customer pays 60 days after delivery. The bakery has $8,000 cash, $30,000 receivables and a $12,000 equipment payment due next month. The owner requests a $25,000 line of credit. Analyze liquidity versus profitability, repayment capacity, receivables timing and financing alternatives. Recommend what information to request, safeguards and a cash-flow monitoring plan.',indicators:['Interpret cash-flow information.','Distinguish profit from liquidity.','Evaluate business credit needs.','Explain financing alternatives.','Assess lending risk and repayment capacity.'],questions:['What would change if the wholesale client paid thirty days late?','Why might a profitable business still run out of cash?']}
];
let currentCase='family',caseDrafts=new Map(),testAnswers=null;
function saveDraft(){caseDrafts.set(currentCase,{transcript:$('transcript').value,photos:[...photos],revealed,feedback,answers:revealed?questions.map((q,i)=>$('answer'+i)?.value||''):[],testAnswers,sessionStarted,deadline,prepDeadline});}
function selectCase(id){if(recording||busy){message('Stop recording and wait for transcription before switching cases.');$('caseselect').value=currentCase;return;}const c=CASE_LIBRARY.find(x=>x.id===id);if(!c)return;saveDraft();currentCase=id;scenario=c.scenario;indicators=[...c.indicators];questions=[...c.questions];const d=caseDrafts.get(id)||{};photos=d.photos||[];revealed=!!d.revealed;feedback=d.feedback||null;testAnswers=d.testAnswers||null;sessionStarted=!!d.sessionStarted;deadline=d.deadline||null;prepDeadline=d.prepDeadline||null;$('transcript').value=d.transcript||'';$('pis').value=indicators.join('\n');$('qs').value='';$('custom').value='';$('questions').replaceChildren();if(revealed){renderQuestions();(d.answers||[]).forEach((a,i)=>$('answer'+i).value=a);}gallery();if(feedback)renderResults();else{$('results').replaceChildren(textNode('div','Complete this case to get its scorecard.','card'));$('download').disabled=true;}lastRecording=null;$('retrytranscribe').hidden=true;$('playback').hidden=true;$('playback').removeAttribute('src');$('recstatus').textContent='Ready';$('clock').textContent=deadline?format(Math.ceil((deadline-Date.now())/1000)):'15:00';$('prepclock').textContent=prepDeadline?format(Math.ceil((prepDeadline-Date.now())/1000)):'30:00';$('caseselect').value=id;$('casetitle').textContent=c.title;$('casebrief').textContent=c.scenario;$('casetag').textContent=c.tag;$('casenote').textContent=c.note;$('samplelink').href=c.source;$('samplelink').textContent=c.tag.startsWith('Original')?'FTDM event reference ↗':'Read source case ↗';$('casepis').replaceChildren(...indicators.map(x=>textNode('li',x)));message('');show(0);controls();}
for(const c of CASE_LIBRARY){const o=document.createElement('option');o.value=c.id;o.textContent=c.title+' · '+c.tag;$('caseselect').append(o);}
$('caseselect').onchange=e=>selectCase(e.target.value);
const originalRenderQuestions=renderQuestions;
renderQuestions=function(){originalRenderQuestions();if(testAnswers)testAnswers.forEach((a,i)=>$('answer'+i).value=a);};
selectCase('family');
$('loaddemo').onclick=()=>{if(recording||busy){message('Wait for recording or transcription to finish.');return;}selectCase('family');photos=TEST_KIT.visuals.map(v=>({name:v.name,url:v.url}));gallery();$('transcript').value=TEST_KIT.transcript;testAnswers=[...TEST_KIT.answers];revealed=false;feedback=null;sessionStarted=false;deadline=null;$('results').replaceChildren();$('download').disabled=true;$('demostatus').textContent='Synthetic test data loaded: 3 visuals, transcript and answers. Answers appear after you reveal questions.';show(1);message('Synthetic test kit loaded. Click Finish presentation & reveal questions, then Evaluate our roleplay.');};
